371→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
372→// Transcripts accumulate across checkpoints — each write splices into the existing
373→// tree. When the ref reaches capacity, generation rotation (future work) archives
374→// the current ref and starts a fresh one.
375→//
376→// sessionIndex is the session slot (0-based), determined by the caller to stay
377→// consistent with the /main ref's session numbering.
378→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
379→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
380→	transcript := opts.Transcript
381→	if len(transcript) == 0 && opts.TranscriptPath != "" {
382→		var readErr error
383→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
384→		if readErr != nil {
385→			transcript = nil
386→		}
387→	}
388→	if len(transcript) == 0 {
389→		return nil // No transcript to write
390→	}
391→
392→	if err := validateWriteOpts(opts); err != nil {
393→		return err
394→	}
395→
396→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
397→	if err := s.ensureRef(refName); err != nil {
398→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
399→	}
400→
401→	parentHash, rootTreeHash, err := s.getRefState(refName)
402→	if err != nil {
403→		return err
404→	}
405→
406→	basePath := opts.CheckpointID.Path() + "/"
407→	checkpointPath := opts.CheckpointID.Path()
408→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
409→
410→	// Read existing entries at this checkpoint's shard path (accumulate, don't replace)
411→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
412→	if err != nil {
413→		return err
414→	}
415→
416→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
417→	if err != nil {
418→		return err
419→	}
420→
421→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
422→		return err
423→	}
424→
425→	// Splice into existing root tree (preserves other checkpoints' transcripts)
426→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
427→	if err != nil {
428→		return err
429→	}
430→
431→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
432→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
433→}
434→
435→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
436→// Returns the redacted transcript bytes so the caller can compute the content hash.
437→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
438→	// Redact secrets before chunking
439→	redacted, err := redact.JSONLBytes(transcript)
440→	if err != nil {
441→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
442→	}
443→
444→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
445→	if err != nil {
446→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
447→	}
448→
449→	for i, chunk := range chunks {
450→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
451→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
452→		if err != nil {
453→			return nil, err
454→		}
455→		entries[chunkPath] = object.TreeEntry{
456→			Name: chunkPath,
457→			Mode: filemode.Regular,
458→			Hash: blobHash,
459→		}
460→	}
461→
462→	return redacted, nil
463→}
464→
465→// validateWriteOpts validates identifiers in WriteCommittedOptions.
466→func validateWriteOpts(opts WriteCommittedOptions) error {
467→	if opts.CheckpointID.IsEmpty() {
468→		return errors.New("invalid checkpoint options: checkpoint ID is required")
469→	}
470→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
471→		return fmt.Errorf("invalid checkpoint options: %w", err)
472→	}
473→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
474→		return fmt.Errorf("invalid checkpoint options: %w", err)
475→	}
476→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
477→		return fmt.Errorf("invalid checkpoint options: %w", err)
478→	}
479→	return nil
480→}
